#ifndef SC_WDT_H
#define SC_WDT_H

#include <stdbool.h>
#include "sc_hal.h"

/* The TPS3823 (board_services) is an EXTERNAL watchdog: the SC keeps  */
/* it happy by STROBING its WDI line.  C2 (project constraint): the    */
/* watchdog must NOT be armed or kicked DURING the power-up sequence,  */
/* only AFTER bring-up has completed -- otherwise a slow rail ramp     */
/* would trip a board reset mid-sequence.  sc_wdt_arm() therefore sets */
/* a latch that sc_wdt_kick() checks; kicks before arming are no-ops.  */

/* Arm the watchdog supervision.  Call ONLY after sc_seq_run() returns  */
/* success -- never inside the bring-up sequence (C2).                  */
void sc_wdt_arm(void);

/* True once armed -- the bring-up code asserts !sc_wdt_is_armed()      */
/* while sequencing.                                                    */
bool sc_wdt_is_armed(void);

/* Strobe the TPS3823 WDI.  A no-op until sc_wdt_arm() has been called  */
/* (C2 guard), so a stray kick during power-up cannot start the timer. */
void sc_wdt_kick(void);

#endif /* SC_WDT_H */
